import{_ as a,o as i,c as t,a2 as o}from"./chunks/framework.iWwp2X7T.js";const f=JSON.parse('{"title":"Diagnosis lifecycle","description":"Mobile Inspector development documentation · Diagnosis lifecycle","frontmatter":{"title":"Diagnosis lifecycle","description":"Mobile Inspector development documentation · Diagnosis lifecycle"},"headers":[],"relativePath":"en/reference/diagnosis.md","filePath":"en/reference/diagnosis.md"}'),r={name:"en/reference/diagnosis.md"};function n(s,e,d,c,l,p){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="diagnosis-lifecycle" tabindex="-1">Diagnosis lifecycle <a class="header-anchor" href="#diagnosis-lifecycle" aria-label="Permalink to &quot;Diagnosis lifecycle&quot;">​</a></h1><h2 id="current-availability" tabindex="-1">Current availability <a class="header-anchor" href="#current-availability" aria-label="Permalink to &quot;Current availability&quot;">​</a></h2><p><code>automaticDiagnosis</code> is false. The Codex adapter rejects with <code>UNSUPPORTED_SANDBOX</code> before Git/model work because effective no-tool enforcement is not certified. The direct Responses adapter is source-tested but provider compatibility remains unaccepted. These are not configurable waivers. Automatic repair (M4) is not implemented.</p><p>Capture, incident browsing and read-only MCP remain independent. Normal startup, pairing and recording make no model request. A real provider attempt needs explicitly selected trusted policy, owner-process credentials and separate authorization; a failed attempt is not permission to retry.</p><h2 id="separate-observation-from-hypothesis" tabindex="-1">Separate observation from hypothesis <a class="header-anchor" href="#separate-observation-from-hypothesis" aria-label="Permalink to &quot;Separate observation from hypothesis&quot;">​</a></h2><p>An incident records facts; a diagnosis is a hypothesis. Incident states include open, diagnosing, diagnosed, needs-input and cancelled. Task states are queued, running, result, failed and cancelled. A failed task does not create an application defect. A recommendation is not edit permission or proof of resolution.</p><h2 id="bounded-orchestration" tabindex="-1">Bounded orchestration <a class="header-anchor" href="#bounded-orchestration" aria-label="Permalink to &quot;Bounded orchestration&quot;">​</a></h2><p>One foreground lease per project, at most four globally. One task executes per project; at most three pending per project and twelve globally. The five-minute deadline covers preparation and runner. Cancellation/deadline publishes a terminal view but retains capacity until termination is confirmed. No timer retries. Quiet-window and duplicate admission remain enforced.</p><p>The direct adapter makes one bounded HTTPS POST with no tools, redirects, retry, fallback or source retrieval. Structured result validation rejects invented evidence, traversal and unknown fields. Safe failures may expose fixed stage/code/HTTP-status details, never raw provider strings or bodies. Local fake-provider success proves only local classification. Start with <a href="./../tutorials/diagnosis">the synthetic lab</a>, which performs no model request.</p>',9)])])}const h=a(r,[["render",n]]);export{f as __pageData,h as default};
